  if (r > 200 && g < 80 && b < 80) return 0;
  if (g > 200 && r < 80 && b < 80) return 1;
  if (b > 200 && r < 80 && g < 80) return 2;
  if (r > 200 && g > 200 && b < 80) return 3;
  if (r > 200 && g < 80 && b > 200) return 4;
